INSERT INTO players (username,display_name,password_hash,email,race_id,title,rank_level,rank_name,glory,reputation,last_turn_at) SELECT 'demo_commander','Demo Commander','$2y$10$O85HAJqPK6eL/dNvwa6Sluz53/oGnz7qBz3WL750u9OaRa46u00Re','demo_commander@localhost',(SELECT id FROM races WHERE name LIKE 'Tau%ri' LIMIT 1),'Commander',3,'Commander',1000,500,NOW() WHERE NOT EXISTS (SELECT 1 FROM players WHERE username='demo_commander');
INSERT INTO player_resources (player_id,naquadah,banked_naquadah,attack_turns,market_turns,untrained_units,unit_production,miners,lifers,attack_units,defense_units,spies,anti_spies,metal,crystal,energy,dark_matter,food,water,population,population_capacity,workforce) SELECT id,1240000,500000,84,3,1600,12,120,12,850,1200,160,140,820000,460000,640,2500,10000,10000,100,1000,100 FROM players WHERE username='demo_commander' AND NOT EXISTS (SELECT 1 FROM player_resources pr WHERE pr.player_id=players.id);
INSERT INTO player_unit_stats(player_id) SELECT id FROM players WHERE username='demo_commander' AND NOT EXISTS (SELECT 1 FROM player_unit_stats pus WHERE pus.player_id=players.id);
